function makeTree(){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.22,.32,2.2,8),new THREE.MeshStandardMaterial({color:0x6b4a2b,roughness:.9}));trunk.position.y=1.1;trunk.castShadow=true;g.add(trunk);const leaf=new THREE.MeshStandardMaterial({color:0x3f6d34,roughness:.9});[[1.7,2.4,2.2],[1.3,3.5,1.9],[.8,4.4,1.5]].forEach(([r,y,h])=>{const c=new THREE.Mesh(new THREE.ConeGeometry(r,h,9),leaf);c.position.y=y;c.castShadow=true;g.add(c)});return g}
function makeBush(){const g=new THREE.Group();const m=new THREE.MeshStandardMaterial({color:0x4a7a3a,roughness:.95});[[-.4,.5,.2,.0],[.4,.45,.0,.2],[0,.75,-.2,.1]].forEach(([x,y,z,s])=>{const b=new THREE.Mesh(new THREE.SphereGeometry(.5+s,8,6),m);b.position.set(x,y,z);b.castShadow=true;g.add(b)});return g}
function makeRock(){const g=new THREE.Group();const r=new THREE.Mesh(new THREE.DodecahedronGeometry(.9,0),new THREE.MeshStandardMaterial({color:0x7d7f80,roughness:.95,flatShading:true}));r.position.y=.5;r.castShadow=true;g.add(r);return g}
function placeProp(kind){const g=kind==='tree'?makeTree():kind==='bush'?makeBush():makeRock();const dir=new THREE.Vector3();camera.getWorldDirection(dir);const px=camera.position.x+dir.x*9,pz=camera.position.z+dir.z*9;g.position.set(px,groundYAt(px,pz),pz);register(g,{id:kind+'-'+Date.now(),name:kind==='tree'?'Tree':kind==='bush'?'Bush':'Rock',category:'landscape',builtin:false});select(g);autosave()}
function createGround(silent){const ex=sceneRegistry.byId('ground');if(ex){if(!silent)select(ex);return ex}const g=new THREE.Mesh(new THREE.PlaneGeometry(4000,4000),new THREE.MeshStandardMaterial({color:0x587047,roughness:1}));g.rotation.x=-Math.PI/2;g.receiveShadow=true;g.position.set(camera.position.x,0,camera.position.z);register(g,{id:'ground',name:'Ground',category:'landscape',builtin:true,ground:true});ground=g;state.groundCreated=true;if(!silent){save();select(g);renderEditor()}return g}
if(state.scene){const q=state.scene;if(q.timeOfDay!=null)timeOfDay=q.timeOfDay;if(q.environmentIntensity!=null)environmentIntensity=q.environmentIntensity;if(q.sun!=null)sun.intensity=q.sun;if(q.hemi!=null)hemi.intensity=q.hemi;if(q.exposure!=null)renderer.toneMappingExposure=q.exposure;if(q.fog!=null){fog.density=q.fog;scene.fog=q.fog?fog:null}if(q.camera?.p)camera.position.fromArray(q.camera.p);if(q.camera?.target)controls.target.fromArray(q.camera.target);if(q.camera?.fov){camera.fov=q.camera.fov;camera.updateProjectionMatrix()}if(q.dof){dofEnabled=false;aperture=q.dof.aperture??aperture;focalMM=q.dof.focalMM??focalMM;updateDOF(true)}if(q.weather){weatherId=(q.weather.id&&WEATHER[q.weather.id])?q.weather.id:weatherId;Object.assign(weatherTarget,WEATHER[weatherId]||{},q.weather);Object.assign(weather,weatherTarget);weatherTint.set(weatherTarget.tint||weather.tint);weatherFrom={...weather};weatherBlend=3}}
if(state.freshSliceV1!==1){state.freshSliceV1=1;state.placed=[];timeOfDay=16;weatherId='clear';Object.assign(weather,WEATHER.clear);weatherTint.set(weather.tint);weatherTintTo.set(weather.tint);weatherFrom={...weather};weatherBlend=3;camera.position.set(10,6,12);controls.target.set(0,1,0);controls.update();save()}
if(state.fogZeroV1!==1){state.fogZeroV1=1;state.scene=state.scene||{};state.scene.fog=0;fog.density=0;scene.fog=null;save()}
