async function showProjects(){const el=$('#projects');if(!el)return;el.hidden=false;const list=await listProjects(),cur=currentProject();el.innerHTML='<div class="projHead"><b>'+icon('world')+' '+t('projectsTitle')+'</b><div class="actions fit"><button data-newplan="1">'+icon('plus')+' '+t('newPlan')+'</button></div></div>'+((list&&list.length)?'<div class="projList">'+list.map(p=>'<div class="projCard'+(p.id===cur?' cur':'')+'"><div class="projThumb">'+(p.thumb?'<img src="data:image/png;base64,'+p.thumb+'" alt="">':icon('world',34))+'</div><div class="projBody"><b title="'+p.name+'">'+p.name+'</b><small>'+fmtDate(p.updatedAt)+'</small></div><div class="projBtns"><button data-open="'+p.id+'">'+icon('arrowRight',14)+' '+t('open')+'</button><button data-pcopy="'+p.id+'" title="'+t('duplicate')+'">'+icon('copy',14)+'</button><button data-prename="'+p.id+'" title="'+t('rename')+'">'+icon('pencil',14)+'</button><button data-pdel="'+p.id+'" title="'+t('delete')+'" '+(p.id==='default'?'disabled':'')+'>'+icon('trash',14)+'</button></div></div>').join('')+'</div>':'<small>'+t('noProjects')+'</small>');el.querySelectorAll('[data-newplan]').forEach(b=>b.onclick=newPlan);el.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{setProject(b.dataset.open);location.reload()});el.querySelectorAll('[data-pcopy]').forEach(b=>b.onclick=async()=>{const p=(list||[]).find(x=>x.id===b.dataset.pcopy);const name=prompt(t('copyNamePrompt'),(p?p.name:'Project')+' copy');if(name==null)return;const r=await duplicateProject(b.dataset.pcopy,name.trim()||'Copy');if(r)showProjects()});el.querySelectorAll('[data-prename]').forEach(b=>b.onclick=async()=>{const p=(list||[]).find(x=>x.id===b.dataset.prename);const name=prompt(t('renamePrompt'),p?p.name:'');if(name==null||!name.trim())return;await renameProject(b.dataset.prename,name.trim());showProjects()});el.querySelectorAll('[data-pdel]').forEach(b=>b.onclick=async()=>{const p=(list||[]).find(x=>x.id===b.dataset.pdel);if(!confirm(t('deletePrompt').replace('{name}',p?p.name:'')))return;await deleteProject(b.dataset.pdel);showProjects()})}
async function newPlan(){const name=prompt(t('projectName'),'Project');if(name==null)return;const p=await createProject((name.trim()||'Project'));if(p&&p.id){setProject(p.id);location.reload()}}
function modelThumb(cat,name,sub){const cv=document.createElement('canvas');cv.width=160;cv.height=104;const x=cv.getContext('2d');const pal={character:['#4a3a2a','#1a1410'],vehicle:['#2a3550','#111823'],landscape:['#2c4526','#101810']}[cat]||['#333a44','#11151c'];const g=x.createLinearGradient(0,0,160,104);g.addColorStop(0,pal[0]);g.addColorStop(1,pal[1]);x.fillStyle=g;x.fillRect(0,0,160,104);try{const p=new Path2D(ICONS[cat]||ICONS.landscape);x.save();x.translate(80-26,44-26);x.scale(2.2,2.2);x.strokeStyle='rgba(255,255,255,.9)';x.lineWidth=1.5;x.stroke(p);x.restore()}catch(e){/* ignore */}x.fillStyle='#fff';x.font='600 12px system-ui';x.fillText(name.slice(0,18),8,90);if(sub){x.fillStyle='rgba(255,255,255,.62)';x.font='10px system-ui';x.fillText(sub,8,102)}return cv.toDataURL()}
