function placeCatalog(it){if(!it)return;if(it.kind==='ground'){createGround();return}if(it.kind==='default'||it.key.startsWith('model:'))return placeDefault(it.id);const src=sceneRegistry.byId(it.id);if(!src)return;const dir=new THREE.Vector3();camera.getWorldDirection(dir);const px=camera.position.x+dir.x*9,pz=camera.position.z+dir.z*9;const c=cloneObjectWithLighting(src);c.userData.editor={...src.userData.editor,id:'copy-'+Date.now(),name:src.userData.editor.name};register(c,c.userData.editor);c.position.set(px,groundYAt(px,pz),pz);snapshotObject(c);select(c);autosave()}
function showCatalog(mode){const el=$('#catalog');if(!el)return;const defs=defaults.filter(a=>a.cat===mode&&!state.purged.includes(a.id)&&!state.deleted.includes(a.id));const imported=objects.filter(o=>o.userData.editor&&o.userData.editor.imported&&o.userData.editor.category===mode);const inv=(mode==='landscape'?[{key:'ground:new',id:'ground',name:t('groundLabel'),cat:'landscape',h:2,kind:'ground'}]:[]).concat(defs.map(a=>({key:'model:'+a.id,id:a.id,name:a.name,cat:a.cat,tris:a.tris,bytes:a.bytes,h:a.h,kind:'default'})),imported.map(o=>({key:'import:'+(o.userData.editor.id||''),id:o.userData.editor.id,name:o.userData.editor.name,cat:o.userData.editor.category,tris:o.userData.editor.tris,bytes:o.userData.editor.bytes,h:4,kind:'import'})));el.hidden=false;el.innerHTML='<div class="catBox"><div class="catHead"><b>'+icon('plus')+' '+t('create')+' · '+t(mode)+'</b><button data-catimport="1">'+icon('upload')+' '+t('importLabel')+'</button></div><input class="catSearch" data-catsearch placeholder="'+t('searchModels')+'"><div class="catGrid">'+(inv.length?inv.map(it=>'<button class="catItem" draggable="true" data-catkey="'+it.key+'" data-catname="'+it.name.toLowerCase()+'"><img class="catImg" src="'+modelThumb(it.cat,it.name,it.tris?fmt(it.tris)+' '+t('trisShort'):'')+'" alt=""><span>'+shortName(it.name)+'</span>'+(it.kind==='import'?'<em class="catTag">'+t('importedTag')+'</em>':'')+'</button>').join(''):'<small>'+t('noModels')+'</small>')+'</div><small>'+t('catalogHint')+'</small></div>';el.querySelectorAll('[data-catkey]').forEach(b=>{const key=b.dataset.catkey,it=inv.find(x=>x.key===key);b.onclick=()=>{hideCatalog();placeCatalog(it)};b.ondragstart=e=>{dragMeta=it;e.dataTransfer.setData('text/plain',key);e.dataTransfer.effectAllowed='copy'};b.ondragend=()=>{dragGhost.visible=false;dragMeta=null}});el.querySelectorAll('[data-catsearch]').forEach(i=>i.oninput=()=>{const q=i.value.trim().toLowerCase();el.querySelectorAll('[data-catname]').forEach(t2=>{t2.style.display=(!q||t2.dataset.catname.includes(q))?'':'none'})});el.querySelectorAll('[data-catimport]').forEach(b=>b.onclick=()=>{pendingImportCat=mode;file.click()});el.onclick=e=>{if(e.target===el)hideCatalog()}}
function hideCatalog(){const el=$('#catalog');if(el)el.hidden=true}
